    fun totalWays(l: Long): Long {
        return (l + 1) * (l + 2) * (l + 3) / 6
    }

    // Ways where the triangle is degenerate or impossible
    // For each stick being the longest, count the cases where the sum of the other two is <= the longest
    fun countInvalid(a: Long, b: Long, c: Long, l: Long): Long {
        var res = 0L
